import React from 'react'
import {graphql, Link} from "gatsby"
import {Helmet} from "react-helmet"
import {MDXRenderer} from "gatsby-plugin-mdx";
import {GatsbyImage, getImage} from "gatsby-plugin-image";
import Navbar from "../components/App/Navbar";
import Layout from "../components/App/Layout";
import Footer from '../components/App/Footer'
import SecondaryPageHeader from "../components/SecondaryPageHeader";
import BlogPostCard from "../components/BlogPostCard";
import BlogPostCTA from "../components/BlogPostCTA";
import '../assets/css/blog-homepage.css';

const SITE_URL = 'https://salspotsoftware.com';
const SITE_NAME = 'Salspot Software';

function withTrailingSlash(urlPath) {
  if (!urlPath) return '/';
  if (urlPath === '/') return '/';
  return urlPath.endsWith('/') ? urlPath : `${urlPath}/`;
}

function formatDate(dateString) {
  if (!dateString) return null;
  const d = new Date(dateString);
  return d.toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
}

function BlogPostSEO({frontmatter, timeToRead, excerpt, siteUrl}) {
  const {title, shortDescription, slug, category, author, publishedAt, headerImage} = frontmatter;
  const description = shortDescription || excerpt;
  const canonical = `${siteUrl}${withTrailingSlash(slug)}`;
  const imageUrl = headerImage?.childImageSharp?.gatsbyImageData?.images?.fallback?.src
    ? `${siteUrl}${headerImage.childImageSharp.gatsbyImageData.images.fallback.src}`
    : null;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: title,
    description,
    author: {'@type': 'Person', name: author},
    publisher: {
      '@type': 'Organization',
      name: SITE_NAME,
      url: siteUrl,
    },
    mainEntityOfPage: {'@type': 'WebPage', '@id': canonical},
    datePublished: publishedAt,
    ...(imageUrl && {image: imageUrl}),
    ...(category && {articleSection: category}),
    ...(timeToRead && {timeRequired: `PT${timeToRead}M`}),
  };

  return (
    <Helmet>
      <title>{`${title} | ${SITE_NAME} Blog`}</title>
      <meta name="description" content={description}/>
      <link rel="canonical" href={canonical}/>

      <meta property="og:type" content="article"/>
      <meta property="og:title" content={title}/>
      <meta property="og:description" content={description}/>
      <meta property="og:url" content={canonical}/>
      <meta property="og:site_name" content={SITE_NAME}/>
      {imageUrl && <meta property="og:image" content={imageUrl}/>}
      {publishedAt && <meta property="article:published_time" content={publishedAt}/>}
      {author && <meta property="article:author" content={author}/>}
      {category && <meta property="article:section" content={category}/>}

      <meta name="twitter:card" content="summary_large_image"/>
      <meta name="twitter:title" content={title}/>
      <meta name="twitter:description" content={description}/>
      {imageUrl && <meta name="twitter:image" content={imageUrl}/>}

      <script type="application/ld+json">{JSON.stringify(jsonLd)}</script>
    </Helmet>
  );
}

function BlogListingSEO({posts, siteUrl}) {
  const title = 'Blog | Salspot Software';
  const description = "Actionable insights on engineering, design, process and strategy from the Salspot Software team.";
  const canonical = `${siteUrl}/blog/`;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Blog',
    name: title,
    description,
    url: canonical,
    publisher: {'@type': 'Organization', name: SITE_NAME, url: siteUrl},
    blogPost: posts.map(({node}) => ({
      '@type': 'BlogPosting',
      headline: node.frontmatter.title,
      url: `${siteUrl}${withTrailingSlash(node.frontmatter.slug)}`,
      datePublished: node.frontmatter.publishedAt,
      author: {'@type': 'Person', name: node.frontmatter.author},
      description: node.frontmatter.shortDescription,
    })),
  };

  return (
    <Helmet>
      <title>{title}</title>
      <meta name="description" content={description}/>
      <link rel="canonical" href={canonical}/>

      <meta property="og:type" content="website"/>
      <meta property="og:title" content={title}/>
      <meta property="og:description" content={description}/>
      <meta property="og:url" content={canonical}/>
      <meta property="og:site_name" content={SITE_NAME}/>

      <meta name="twitter:card" content="summary_large_image"/>
      <meta name="twitter:title" content={title}/>
      <meta name="twitter:description" content={description}/>

      <script type="application/ld+json">{JSON.stringify(jsonLd)}</script>
    </Helmet>
  );
}

function ReadingProgress() {
  const [progress, setProgress] = React.useState(0);

  React.useEffect(() => {
    const handleScroll = () => {
      const article = document.querySelector('.blog-article-prose');
      if (!article) return;
      const rect = article.getBoundingClientRect();
      const articleTop = rect.top + window.scrollY;
      const articleHeight = article.offsetHeight;
      const windowHeight = window.innerHeight;
      const scrolled = window.scrollY - articleTop + windowHeight * 0.3;
      const total = articleHeight;
      const pct = Math.min(100, Math.max(0, (scrolled / total) * 100));
      setProgress(pct);
    };
    window.addEventListener('scroll', handleScroll, {passive: true});
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="blog-reading-progress" style={{transform: `scaleX(${progress / 100})`}} />
  );
}

export default function BlogHomepage({data}) {
  const isBlogPost = data?.mdx?.frontmatter?.key === 'blog-post';
  const articleImage = getImage(data?.mdx?.frontmatter?.headerImage?.childImageSharp?.gatsbyImageData);

  return (
    <Layout>
      <Navbar className="navbar-fixed-top white-page"/>
      {isBlogPost ? (
        <>
          <BlogPostSEO
            frontmatter={data.mdx.frontmatter}
            timeToRead={data.mdx.timeToRead}
            excerpt={data.mdx.excerpt}
            siteUrl={SITE_URL}
          />
          <ReadingProgress />

          <article className="blog-post">
            <header className="blog-post-header">
              <div className="blog-post-header-inner">
                <div className="blog-post-meta-top">
                  <Link to="/blog/" className="blog-post-back">
                    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
                      <path d="M12.5 15L7.5 10L12.5 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                    All articles
                  </Link>
                </div>
                <span className="blog-post-category">{data.mdx.frontmatter.category}</span>
                <h1 className="blog-post-title">{data.mdx.frontmatter.title}</h1>
                {data.mdx.frontmatter.shortDescription && (
                  <p className="blog-post-subtitle">{data.mdx.frontmatter.shortDescription}</p>
                )}
                <div className="blog-post-byline">
                  <div className="blog-post-author-avatar">
                    {data.mdx.frontmatter.author?.charAt(0)}
                  </div>
                  <div className="blog-post-author-info">
                    <span className="blog-post-author-name">{data.mdx.frontmatter.author}</span>
                    <div className="blog-post-meta-details">
                      {data.mdx.frontmatter.publishedAt && (
                        <time dateTime={data.mdx.frontmatter.publishedAt}>
                          {formatDate(data.mdx.frontmatter.publishedAt)}
                        </time>
                      )}
                      {data.mdx.timeToRead && (
                        <>
                          <span className="blog-post-meta-sep">&middot;</span>
                          <span>{data.mdx.timeToRead} min read</span>
                        </>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </header>

            {articleImage && (
              <div className="blog-post-hero">
                <GatsbyImage alt={data.mdx.frontmatter.title} image={articleImage}/>
              </div>
            )}

            <div className="blog-post-body">
              <div className="blog-article-prose">
                <MDXRenderer>{data.mdx.body}</MDXRenderer>
              </div>
            </div>

            <footer className="blog-post-footer">
              <div className="blog-post-tags">
                <span className="blog-post-tag">{data.mdx.frontmatter.category}</span>
              </div>
              <div className="blog-post-share">
                <span className="blog-post-share-label">Share this article</span>
                <a
                  href={`https://twitter.com/intent/tweet?text=${encodeURIComponent(data.mdx.frontmatter.title)}&url=${encodeURIComponent(SITE_URL + withTrailingSlash(data.mdx.frontmatter.slug))}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="blog-post-share-link"
                  aria-label="Share on Twitter"
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
                </a>
                <a
                  href={`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(SITE_URL + withTrailingSlash(data.mdx.frontmatter.slug))}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="blog-post-share-link"
                  aria-label="Share on LinkedIn"
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/></svg>
                </a>
              </div>
            </footer>

            <BlogPostCTA />
          </article>
        </>
      ) : (
        <>
          <BlogListingSEO posts={data.allMdx.edges} siteUrl={SITE_URL}/>
          <div className="blog-listing">
            <header className="blog-listing-header">
              <div className="blog-listing-header-inner">
                <span className="blog-listing-label">Blog</span>
                <h1 className="blog-listing-title">Ideas are great.<br/>Results are better.</h1>
                <p className="blog-listing-subtitle">We're turning our experience into actionable insights on engineering, design, process and strategy.</p>
              </div>
            </header>
            <section className="blog-listing-grid">
              <div className="blog-listing-grid-inner">
                {data.allMdx.edges.map(({node}) => (
                  <BlogPostCard key={node.id} postDetails={node.frontmatter} timeToRead={node.timeToRead}/>
                ))}
              </div>
            </section>
          </div>
        </>
      )}
      <Footer/>
    </Layout>
  )
}

export const query = graphql`
    query BlogHomeQuery($id: String!) {
        allMdx(
            filter: { frontmatter: { key: { eq: "blog-post" } } }
            sort: { fields: [frontmatter___publishedAt, frontmatter___slug], order: [DESC, DESC] }) {
            edges {
                node {
                    id
                    timeToRead
                    frontmatter {
                        key
                        publishedAt
                        slug
                        title
                        category
                        headerImage {
                            childImageSharp {
                                gatsbyImageData
                            }
                        }
                        author
                        shortDescription
                    }
                }
            }
        }
        mdx(id: { eq: $id }) {
            id
            body
            timeToRead
            excerpt(pruneLength: 160)
            frontmatter {
                key
                slug
                title
                category
                author
                publishedAt
                shortDescription
                headerImage {
                    childImageSharp {
                        gatsbyImageData(width: 1200, quality: 90)
                    }
                }
            }
        }
    }
`;
